/* Solar Dusk Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="solar-dusk-light"] {
  --background: hsl(40 98.12% 97.89%);
  --foreground: hsl(20.95 21.67% 24.87%);
  --card: hsl(36 47.29% 95.42%);
  --card-foreground: hsl(20.95 21.67% 24.87%);
  --popover: hsl(36 47.29% 95.42%);
  --popover-foreground: hsl(20.95 21.67% 24.87%);
  --primary: hsl(27.04 99.37% 36.06%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(34.35 64.78% 72.84%);
  --secondary-foreground: hsl(33.34 5.76% 31.86%);
  --muted: hsl(39.13 44.23% 90.62%);
  --muted-foreground: hsl(24.98 4.57% 44.34%);
  --accent: hsl(34.29 68.36% 83.93%);
  --accent-foreground: hsl(33.34 5.76% 31.86%);
  --destructive: hsl(360 70.13% 34.87%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(43.5 43.24% 82.05%);
  --input: hsl(43.5 43.24% 82.05%);
  --ring: hsl(27.04 99.37% 36.06%);
  --chart-1: hsl(27.04 99.37% 36.06%);
  --chart-2: hsl(24.98 4.57% 44.34%);
  --chart-3: hsl(35.5 92.27% 32.54%);
  --chart-4: hsl(24.98 4.57% 44.34%);
  --chart-5: hsl(39.77 86.61% 42.25%);
  --radius: 0.3rem;
  --sidebar: hsl(39.13 44.23% 90.62%);
  --sidebar-foreground: hsl(20.95 21.67% 24.87%);
  --sidebar-primary: hsl(27.04 99.37% 36.06%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(35.5 92.27% 32.54%);
  --sidebar-accent-foreground: hsl(300 50% 100%);
  --sidebar-border: hsl(43.5 43.24% 82.05%);
  --sidebar-ring: hsl(27.04 99.37% 36.06%);
  --font-sans: Oxanium, sans-serif;
  --font-serif: Merriweather, serif;
  --font-mono: Fira Code, monospace;
  --shadow-color: hsl(28 18% 25%);
  --shadow-opacity: 0.18;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 2px 3px 0px hsl(28 18% 25% / 0.09);
  --shadow-xs: 0px 2px 3px 0px hsl(28 18% 25% / 0.09);
  --shadow-sm:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 1px 2px -1px hsl(28 18% 25% / 0.18);
  --shadow:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 1px 2px -1px hsl(28 18% 25% / 0.18);
  --shadow-md:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 2px 4px -1px hsl(28 18% 25% / 0.18);
  --shadow-lg:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 4px 6px -1px hsl(28 18% 25% / 0.18);
  --shadow-xl:
    0px 2px 3px 0px hsl(28 18% 25% / 0.18),
    0px 8px 10px -1px hsl(28 18% 25% / 0.18);
  --shadow-2xl: 0px 2px 3px 0px hsl(28 18% 25% / 0.45);
  --tracking-normal: 0em;
}

